import{_ as a,o as t,c as s,ag as r}from"./chunks/framework.Ccn6roXv.js";const u=JSON.parse('{"title":"4. The request lifecycle","description":"The path from a browser call to parsed data and handler execution.","frontmatter":{"title":"4. The request lifecycle","description":"The path from a browser call to parsed data and handler execution."},"headers":[],"relativePath":"guide/04-request-lifecycle.md","filePath":"guide/04-request-lifecycle.md"}'),i={name:"guide/04-request-lifecycle.md"};function n(l,e,o,p,d,c){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="the-request-lifecycle" tabindex="-1">The request lifecycle <a class="header-anchor" href="#the-request-lifecycle" aria-label="Permalink to &quot;The request lifecycle&quot;">​</a></h1><p>A server function call looks like a function call in application code. At runtime, it is a request.</p><p>The useful mental model is a pipeline.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser call</span></span>
<span class="line"><span>  -&gt; HTTP request</span></span>
<span class="line"><span>  -&gt; framework route</span></span>
<span class="line"><span>  -&gt; deserialization</span></span>
<span class="line"><span>  -&gt; input validation</span></span>
<span class="line"><span>  -&gt; handler</span></span>
<span class="line"><span>  -&gt; serialized response</span></span></code></pre></div><h2 id="browser-call" tabindex="-1">Browser call <a class="header-anchor" href="#browser-call" aria-label="Permalink to &quot;Browser call&quot;">​</a></h2><p>The browser code calls a generated client stub. The stub knows the server function identifier and method.</p><p>The developer sees a friendly API. A tester sees an HTTP request.</p><h2 id="http-request" tabindex="-1">HTTP request <a class="header-anchor" href="#http-request" aria-label="Permalink to &quot;HTTP request&quot;">​</a></h2><p>TanStack Start server function requests commonly use paths under:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_serverFn/</span></span></code></pre></div><p>The request may be <code>POST</code> with a body, or <code>GET</code> with a payload in the query string.</p><h2 id="deserialization" tabindex="-1">Deserialization <a class="header-anchor" href="#deserialization" aria-label="Permalink to &quot;Deserialization&quot;">​</a></h2><p>The framework decodes the request into JavaScript values.</p><p>This happens before the developer&#39;s validator runs.</p><p>If deserialization fails, the handler should not run.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>The validator receives the deserialized value and decides whether it matches the expected shape.</p><p>Strict validation rejects unexpected fields. Loose validation may keep them.</p><h2 id="handler" tabindex="-1">Handler <a class="header-anchor" href="#handler" aria-label="Permalink to &quot;Handler&quot;">​</a></h2><p>The handler runs only after the framework reaches application code.</p><p>This is where state changes, database reads, and authorization checks usually happen.</p><h2 id="security-property" tabindex="-1">Security property <a class="header-anchor" href="#security-property" aria-label="Permalink to &quot;Security property&quot;">​</a></h2><p>The property to preserve is stage separation:</p><ul><li>Wire format errors stop before validation.</li><li>Validation errors stop before the handler.</li><li>Authorization failures stop before state changes.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Next, learn why TanStack Start request bodies do not look like ordinary JSON.</p>`,26)])])}const f=a(i,[["render",n]]);export{u as __pageData,f as default};
